import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1785319710000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><p>Q: What is Sudoku?</p><p>A: Sudoku is the classic logic-based number placement puzzle, reimagined for modern Apple devices. Fill a 9×9 grid so that every row, column, and 3×3 box contains digits 1–9 exactly once. It&#39;s a universal app supporting iPhone, iPad, and Mac with iCloud sync.</p><p>Q: Which devices are supported?</p><p>A: Sudoku is a universal app optimized for iPhone, iPad, and Mac with native controls and crisp Retina display graphics. It requires iOS/iPadOS 16.0 or later and macOS 15.0 (Sequoia) or later. One purchase works on all supported devices.</p><p>Q: How do I download and install Sudoku?</p><p>A: Download Sudoku from the App Store: <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a> — the universal app works on iPhone, iPad, and Mac.</p><p>Q: Does Sudoku need an internet connection?</p><p>A: Core gameplay is 100% offline — no internet needed to play puzzles. Optional features that require internet include iCloud sync (for cross-device progress), Game Center (leaderboards/achievements), and the &quot;More Apps&quot; section in Settings.</p><p>Q: Are there ads or in-app purchases?</p><p>A: No. Sudoku is completely ad-free with no pop-ups, no in-app purchases, and no interruptions. Just pure, focused puzzle gameplay.</p><p>Q: What difficulty levels are available?</p><p>A: Five difficulty levels with different numbers of given cells:</p><ul><li><strong>Easy</strong> — 45 givens (great for beginners)</li><li><strong>Medium</strong> — 36 givens (balanced challenge)</li><li><strong>Hard</strong> — 31 givens (requires deduction techniques)</li><li><strong>Expert</strong> — 27 givens (for experienced solvers)</li><li><strong>Master</strong> — 24 givens (the ultimate challenge)</li></ul><p>Each puzzle is uniquely generated — you&#39;ll never play the same puzzle twice.</p><p>Q: Is my game data synced across devices?</p><p>A: Yes! When you sign into iCloud, your game saves, statistics, settings, and daily challenge progress automatically sync across all your Apple devices via CloudKit.</p><p>Q: Does Sudoku save my progress if I quit?</p><p>A: Yes. Your current game is saved automatically so you can continue right where you left off. The home screen shows a &quot;Continue&quot; card with your active puzzle.</p><p>Q: How do I update the app?</p><p>A: App Store users receive updates automatically. To check manually, open the App Store and go to your Account → Updates section.</p><p>Q: How do I report bugs or request features?</p><p>A: Open an issue in the project repository and include your device type, iOS/macOS version, Sudoku version, reproduction steps, and screenshots if available.</p><p>Q: Can I customize the appearance?</p><p>A: Yes! Choose from 8 beautiful themes (Classic, Midnight, Paper, Forest, Ocean, Sunset, Lavender, Rose) in Settings. You can also toggle sound effects on/off.</p><p>Q: How many languages are supported?</p><p>A: 25 languages, switchable at runtime without restarting: English, Chinese (Simplified &amp; Traditional), Japanese, Korean, French, German, Spanish, Italian, Russian, Portuguese, Dutch, Vietnamese, Thai, Hindi, Turkish, Greek, Finnish, Norwegian, Danish, Hungarian, Indonesian, Malay, Ukrainian, and German (Switzerland).</p><p>Q: What are the keyboard shortcuts on Mac?</p><p>A: <code>⌘N</code> for a new game, <code>⌘Z</code> to undo, and <code>⌘1</code> through <code>⌘5</code> to start a new game at each difficulty level (Easy through Master).</p><p>Q: Can I print puzzles?</p><p>A: Yes! On Mac, use the Print feature to generate printable puzzles at any difficulty level, with optional answer keys included.</p><p>If you need more answers, please open an issue in the repository or consult the full documentation.</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};